const results = [];

for (const item of $input.all()) {
  const json = item.json;

  const tipe = json['Tipe Transaksi'];
  if (
    tipe !== 'Pembayaran' &&
    tipe !== 'Pengeluaran' &&
    tipe !== 'Penerimaan'
  ) {
    continue;
  }

  const rawDate = (json['Tanggal Transaksi'] || '')
    .toString().trim();
  const dateParts = rawDate.split('/');
  if (dateParts.length !== 3) continue;

  const cleanDate =
    `${dateParts[2]}-${dateParts[1]}-${dateParts[0]}`;

  const rawAmount =
    (json['Jumlah (IDR)'] || '0').toString();
  const cleanAmount = parseInt(
    rawAmount.replace(/[^0-9]/g, ''), 10
  );

  const matchKey = `${cleanDate}_${cleanAmount}`;

  results.push({
    json: {
      ...json,
      clean_date: cleanDate,
      clean_amount: cleanAmount,
      match_key: matchKey,
      sumber: 'Internal'
    }
  });
}

return results;

const results = [];

for (const item of $input.all()) {
  const json = item.json;

  // Ubah tanggal Excel menjadi YYYY-MM-DD
  const rawDate = json['Tanggal Bank'];
  let cleanDate = '';

  if (typeof rawDate === 'number') {
    const date = new Date(Date.UTC(1899, 11, 30) + rawDate * 86400000);
    cleanDate = date.toISOString().slice(0, 10);
  } else {
    const dateParts = String(rawDate || '').trim().split('/');
    if (dateParts.length === 3) {
      cleanDate = `${dateParts[2]}-${dateParts[1]}-${dateParts[0]}`;
    }
  }

  if (!cleanDate) continue;

  // Bersihkan nominal
  const rawAmount = String(json['Jumlah (IDR)'] ?? '0');
  const cleanAmount = parseInt(rawAmount.replace(/[^0-9]/g, ''), 10);

  if (Number.isNaN(cleanAmount)) continue;

  results.push({
    json: {
      ...json,
      clean_date: cleanDate,
      clean_amount: cleanAmount,
      match_key: `${cleanDate}_${cleanAmount}`,
      sumber: 'Bank'
    }
  });
}

return results;

const items = $input.all();
const groups = {};

for (const item of items) {
  const json = item.json;
  const key = json.match_key;

  if (!key) continue;

  if (!groups[key]) {
    groups[key] = {
      internal: [],
      bank: []
    };
  }

  if (json.sumber === 'Internal') {
    groups[key].internal.push(json);
  } else if (json.sumber === 'Bank') {
    groups[key].bank.push(json);
  }
}

const results = [];

for (const [key, group] of Object.entries(groups)) {
  const internal = group.internal;
  const bank = group.bank;

  let status;
  let pesan;
  let prioritas;

  if (internal.length > 0 && bank.length > 0) {
    status = 'MATCHED';
    pesan = 'Transaksi cocok antara data Internal dan Bank.';
    prioritas = 'Rendah';
  } else if (internal.length > 0) {
    status = 'MISSING IN BANK';
    pesan = 'Transaksi ada di Internal tetapi tidak ditemukan di Bank.';
    prioritas = 'Tinggi';
  } else {
    status = 'UNRECORDED INTERNAL';
    pesan = 'Transaksi ada di Bank tetapi tidak ditemukan di Internal.';
    prioritas = 'Tinggi';
  }

  const data = internal[0] || bank[0];

  results.push({
    json: {
      Tanggal: data.clean_date,
      Nominal: data.clean_amount,
      Status: status,
      Pesan: pesan,
      Prioritas: prioritas,
      Internal_ID: internal.map(x => x['ID Referensi'] || '').join(', '),
      Bank_ID: bank.map(x => x['ID Transaksi Bank'] || '').join(', '),
      Deskripsi: data['Deskripsi Transaksi'] || '',
      Match_Key: key,
      Sources: [
        ...(internal.length ? ['Internal'] : []),
        ...(bank.length ? ['Bank'] : [])
      ].join(', ')
    }
  });
}

return results;

